// One row per state, sorted by lab count (most labs first).
export function listStates() {
  const counts = new Map();
  for (const lab of ALL_BIS_LABS) {
    counts.set(lab.state, (counts.get(lab.state) ?? 0) + 1);
  }
  return Array.from(counts.entries())
    .map(([state, count]) => ({ state, count }))
    .sort((a, b) => b.count - a.count);
}

export function filterByState(labs, state) {
  if (!state || state === 'all') return labs;
  return labs.filter((lab) => lab.state === state);
}

export function filterByCity(labs, city) {
  if (!city) return labs;
  const q = city.toLowerCase();
  return labs.filter((lab) => lab.city.toLowerCase() === q);
}

// Matches name, code, city, state, or pincode.
export function searchByText(labs, query) {
  const q = query.trim().toLowerCase();
  if (!q) return labs;
  return labs.filter(
    (lab) =>
      lab.name.toLowerCase().includes(q) ||
      lab.code.toLowerCase().includes(q) ||
      lab.city.toLowerCase().includes(q) ||
      lab.state.toLowerCase().includes(q) ||
      lab.pincode.includes(q)
  );
}

// One row per primary category, sorted by lab count (most labs first).
export function listPrimaryCategories() {
  const counts = new Map();
  for (const lab of ALL_BIS_LABS) {
    counts.set(lab.primaryCategory, (counts.get(lab.primaryCategory) ?? 0) + 1);
  }
  return Array.from(counts.entries())
    .map(([category, count]) => ({ category, count }))
    .sort((a, b) => b.count - a.count);
}

// Secondary categories available *within* a given primary category's labs
// (a lab's own secondary list, or any other lab sharing that primary).
export function listSecondaryCategories(labs) {
  const set = new Set();
  for (const lab of labs) {
    for (const c of lab.secondaryCategories) set.add(c);
  }
  return Array.from(set).sort();
}

export function filterByPrimaryCategory(labs, category) {
  if (!category || category === 'all') return labs;
  return labs.filter((lab) => lab.primaryCategory === category);
}

export function filterBySecondaryCategory(labs, category) {
  if (!category || category === 'all') return labs;
  return labs.filter((lab) => lab.secondaryCategories.includes(category));
}
